-- Complete Bangladesh administrative hierarchy (division -> district -> upazila)
-- Source: nuhil/bangladesh-geocode. Stable UUIDs via md5('bd-<level>-'||src).
delete from upazila; delete from district; delete from division;

insert into division (id, name_bn, name_en)
select md5('bd-division-'||v.src)::uuid, v.bn, v.en
from (values ('1','চট্টগ্রাম','Chattagram'),('2','রাজশাহী','Rajshahi'),('3','খুলনা','Khulna'),('4','বরিশাল','Barisal'),('5','সিলেট','Sylhet'),('6','ঢাকা','Dhaka'),('7','রংপুর','Rangpur'),('8','ময়মনসিংহ','Mymensingh')) v(src,bn,en);

